# guion.py: un "LLM" falso que sigue un guion fijo.
# Sirve para ver qué hace el harness sin API key y sin gastar tokens.
from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult


class ModeloGuion(BaseChatModel):
    """Devuelve, en orden, los AIMessage de `guion` y anota lo que recibe."""

    guion: list[AIMessage] = []
    llamadas: list = []        # los mensajes que recibió en cada llamada
    tools_vistas: list = []    # los nombres de las tools que le ofrecieron

    @property
    def _llm_type(self) -> str:
        return "guion"

    def bind_tools(self, tools, **kwargs):
        self.tools_vistas = [t["name"] if isinstance(t, dict) else t.name for t in tools]
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        self.llamadas.append(messages)
        respuesta = self.guion[min(len(self.llamadas), len(self.guion)) - 1]
        return ChatResult(generations=[ChatGeneration(message=respuesta)])
